// Repro, bucket A (data_byte): data bits must be sent least significant first.
module tb_uart_repro;
    localparam integer CPB    = 4;
    localparam integer CLK_NS = 10;
    localparam integer BIT_NS = CPB * CLK_NS;

    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #(CLK_NS / 2) clk = ~clk;

    reg [8*64-1:0] nonce;
    integer passed = 0;
    integer failed = 0;
    integer i;
    reg     done = 1'b0;

    task send_and_check_data(input [7:0] d);
        begin
            while (busy) @(posedge clk);
            repeat (3) @(posedge clk);
            @(negedge clk);
            data  = d;
            start = 1'b1;
            @(posedge clk);                 // start bit begins at this edge
            #(CLK_NS / 2) start = 1'b0;
            #(BIT_NS + 25 - CLK_NS / 2);    // middle of data bit 0
            for (i = 0; i < 8; i = i + 1) begin
                if (tx === d[i]) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $display("CHECK DATA_BIT failed: byte %h bit %0d expected %b got %b", d, i, d[i], tx);
                end
                if (i < 7) #(BIT_NS);
            end
        end
    endtask

    initial begin
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        repeat (3) @(posedge clk);
        @(negedge clk) rst = 1'b0;
        send_and_check_data(8'h01);
        send_and_check_data(8'h0F);
        send_and_check_data(8'hD2);
        send_and_check_data(8'h80);
        done = 1'b1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #20000;
        if (!done) begin
            $display("CHECK TIMEOUT failed");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
            $finish;
        end
    end
endmodule
