`timescale 1ns / 1ps
// Repro, bucket C (frame_period): a frame is 11 bit times, so with start held
// high, successive start bits must be at least 11*CLKS_PER_BIT clocks apart.
// Data 8'h00 gives exactly one falling edge of tx per frame (the start bit),
// whatever the bit order or parity value.
module tb_uart_repro;
    localparam integer CPB    = 4;
    localparam integer CLK_NS = 10;
    localparam integer MIN_NS = 11 * CPB * CLK_NS;

    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #(CLK_NS / 2) clk = ~clk;

    reg [8*64-1:0] nonce;
    integer passed = 0;
    integer failed = 0;
    integer edges = 0;
    time    last_fall = 0;
    time    gap;
    reg     done = 1'b0;

    always @(negedge tx) begin
        if (!rst && !done) begin
            if (edges > 0) begin
                gap = $time - last_fall;
                if (gap >= MIN_NS) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $display("CHECK FRAME_PERIOD failed: start bits %0t apart, minimum %0d", gap, MIN_NS);
                end
            end
            last_fall = $time;
            edges = edges + 1;
        end
    end

    initial begin
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        repeat (3) @(posedge clk);
        @(negedge clk);
        data  = 8'h00;
        start = 1'b1;
        rst   = 1'b0;
        wait (edges >= 4);
        done = 1'b1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #20000;
        if (!done) begin
            $display("CHECK TIMEOUT failed");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
            $finish;
        end
    end
endmodule
